// Runtime lookup for a player's current club, from the static ESPN snapshot
// (`player-clubs.data.ts`, generated by scripts/wc2026-build-player-clubs.mjs).
// Clubs don't change during the tournament, so this is captured once. The
// normalization here MUST match the generator's `norm()` exactly.
//
// Keyed by `${fifaCode}|${normName}`, not name alone — same-named players across
// squads (two "Emiliano Martínez") would otherwise collide. Callers pass the
// player's nation code, which equals ESPN's abbreviation in the generator.

import { PLAYER_CLUBS } from './player-clubs.data.js';

function norm(name: string): string {
  return name.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

export function clubFor(name: string, code: string): string | null {
  return PLAYER_CLUBS[`${code}|${norm(name)}`] ?? null;
}
